package com.saumya.pos.fulfillment;
import com.saumya.pos.identity.CustomerAccess;import com.saumya.pos.security.AuthorizationContext;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class ShipmentServiceAuthorizationBoundaryTest {
 @Test void deniedVendorCallsStopBeforePersistence(){var db=mock(JdbcTemplate.class);var auth=mock(AuthorizationContext.class);when(auth.current()).thenReturn(new AuthorizationContext.Context("v@test",7L,1L,"7:v@test",Set.of("POS_VIEW"),false,false,true));var s=new ShipmentService(db,auth,mock(CustomerAccess.class));assertThatThrownBy(s::eligibleOrders).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(s::shipments).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->s.createShipment("o","c","t",null,"r")).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->s.addEvent(1,"IN_TRANSIT","moving","r")).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(db);}
 @Test void customerCanOnlyReadTrackingAfterResolvingOwnedOrder(){var db=mock(JdbcTemplate.class);var auth=mock(AuthorizationContext.class);var ca=mock(CustomerAccess.class);when(ca.resolve("buyer@test")).thenReturn(77L);var t=Timestamp.from(Instant.parse("2026-11-26T08:00:00Z"));when(db.queryForList(contains("FROM orders WHERE id=? AND customer_id=?"),eq("owned"),eq(77L))).thenReturn(List.of(Map.of("tenant_id",7L,"sales_channel","ONLINE")));when(db.queryForList(contains("FROM shipments WHERE tenant_id=? AND order_id=?"),eq(7L),eq("owned"))).thenReturn(List.of(Map.of("id",2L,"carrier","Carrier","tracking_reference","T-1","tracking_url", "https://carrier.test/t","created_at",t)));when(db.queryForList(contains("FROM shipment_events WHERE tenant_id=? AND shipment_id=?"),eq(7L),eq(2L))).thenReturn(List.of(Map.of("id",3L,"event_code","IN_TRANSIT","description","On the way","occurred_at",t)));var result=new ShipmentService(db,auth,ca).customerShipments("buyer@test","owned");assertThat(result).hasSize(1);assertThat(result.getFirst().events().getFirst().description()).isEqualTo("On the way");verify(ca).resolve("buyer@test");}
 @Test void foreignCustomerOrderReturns404BeforeShipmentLookup(){var db=mock(JdbcTemplate.class);var ca=mock(CustomerAccess.class);when(ca.resolve("buyer@test")).thenReturn(77L);when(db.queryForList(contains("FROM orders WHERE id=? AND customer_id=?"),eq("foreign"),eq(77L))).thenReturn(List.of());assertThatThrownBy(()->new ShipmentService(db,mock(AuthorizationContext.class),ca).customerShipments("buyer@test","foreign")).isInstanceOfSatisfying(ResponseStatusException.class,e->assertThat(e.getStatusCode().value()).isEqualTo(404));verify(db).queryForList(contains("FROM orders WHERE id=? AND customer_id=?"),eq("foreign"),eq(77L));verifyNoMoreInteractions(db);}
}
